function track(o){things.push(o);return o}function pos(o,x,z){o.position.set(x,0,z);return o}let lastToast='',lastToastAt=-99;function alert(s,t=3){if(s===lastToast&&time-lastToastAt<8)return;lastToast=s;lastToastAt=time;$('#toast').textContent=s;toastTime=t}
function tone(f=440,d=.15,type='sine',vol=.04){if(!sound||!audio)return;let o=audio.createOscillator(),a=audio.createGain();o.type=type;o.frequency.value=f;a.gain.setValueAtTime(vol,audio.currentTime);a.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+d);o.connect(a);a.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
