function modal(html,buttons=[]){joystick.x=joystick.z=0;$('#stick i').style.transform='';keys={};$('#close').hidden=requiredFlow;$('#modalContent').innerHTML=html;$('#modalButtons').replaceChildren();for(let [s,fn,primary]of buttons){let b=document.createElement('button');b.textContent=s;b.className=primary?'primary':'';b.onclick=fn;$('#modalButtons').append(b)}if(!$('#modal').open)$('#modal').showModal()}
