function showMenu(){mode='menu';resetWorld();mode='menu';pos(hero,innerWidth<650?-.8:3,innerWidth<650?6:2);hero.rotation.y=.3;companion.visible=true;pos(companion,innerWidth<650?.8:4.1,innerWidth<650?6.3:1);companion.rotation.y=-.2;$('#menu').hidden=false;$('#hud').hidden=true;$('#controls').hidden=true;$('#hint').hidden=true;$('#toast').textContent='';$('#vitals').innerHTML='';if(typeof pendingButton!=='undefined')pendingButton.hidden=!save.pending;$('#start').innerHTML=(save.training?'Continuar · nível '+save.level:'Entrar no nosso mundo')+' <span>↗</span>';persist()}
function start(){enableAudio();if(!save.training){startArena(true);modal('<div class="eyebrow">PRÓLOGO · EU E VOCÊ</div><h2>Vamos aprender juntos.</h2><p>Aqui eu sou seu parceiro de treino, representado por um personagem do jogo. Mova o analógico à esquerda para andar. Arraste o cenário à direita para girar a câmera.</p><p>Quando a estrela se aproximar, o círculo aos seus pés fica dourado. Toque em <b>REBATER</b>. Sua direção de movimento dá a curva da devolução. No treino, errar não tira vida.</p>',[['Treinar com você',closeModal,true],['Meu cantinho',showMenu]])}else startLevel()}
function startLevel(){let n=(save.level-1)%6;if(n===0)startArena(false);if(n===1)startDefense();if(n===2)startGarden();if(n===3)startRhythm();if(n===4)startRestaurant();if(n===5)startFishing()}
function startArena(training=false){mode=training?'training':'arena';resetWorld();pos(hero,0,6);hero.rotation.y=Math.PI;facing.set(0,0,-1);yaw=0;state={training,hits:0,goal:3,chapter:(save.level-1)%chapters.length,enemy:0,enemies:[],ball:null,velocity:V(),incoming:true,travel:0,cooldown:0,flight:0,trail:[],rally:0};
if(training){companion.visible=true;pos(companion,0,-5);state.enemies=[{model:companion,hp:3,max:3,name:'Seu amor · treino'}]}else{for(let i=0;i<3;i++){let a=(i-1)*1.35;let o=track(shadowEnemy(Math.sin(a)*8,-Math.cos(a)*8));o.rotation.y=Math.PI;state.enemies.push({model:o,hp:2+Math.min(3,Math.floor(save.level/5)),max:2+Math.min(3,Math.floor(save.level/5)),name:chapters[(state.chapter+i)%6].name,chapter:(state.chapter+i)%6})}}
state.ball=track(mesh(new T.SphereGeometry(.19,16,12),'#ffe4a9',0,1.1,-4,scene,.9));let light=new T.PointLight('#ffe3aa',1.4,4);state.ball.add(light);for(let i=0;i<18;i++){let m=track(mesh(new T.SphereGeometry(.045,6,5),'#edd9b0',0,-10,0,scene,.6));m.material=m.material.clone();state.trail.push(m)}state.circle=track(ring(0,6,1.65));state.velocity.set(0,0,2.5);$('#modeName').textContent=training?'PRÓLOGO · UM TREINO COM VOCÊ':'JARDIM DAS ESTRELAS';$('#title').textContent=training?'Aprender, sem pressa':'Nível '+save.level+' · Enfrentar juntos';$('#objective').textContent=training?'Devolva 3 estrelas. Aqui os erros não machucam.':'Ande, dê curva à estrela e enfrente uma sombra por vez.';alert(training?'Eu estou aqui. Vamos tentar juntos.':'As dificuldades não são nenhum de vocês.');updateHud()}
function enemy(){return state.enemies?.[state.enemy]}
function launchIncoming(){let e=enemy();if(!e)return;state.incoming=true;state.travel=0;state.rally++;state.ball.visible=true;state.ball.position.copy(e.model.position).add(V(0,1.1,0));state.velocity.copy(hero.position).sub(e.model.position).normalize().multiplyScalar(2.5);for(let m of state.trail)m.position.copy(state.ball.position)}
function parry(){if(!['training','arena'].includes(mode)||paused||$('#modal').open||winPending||state.cooldown>0)return;state.cooldown=.38;hero.userData.swing=1;let d=dist(hero.position,state.ball.position);if(state.incoming&&d<2.1){state.incoming=false;state.travel=0;let speed=mode==='training'?5:6+Math.min(save.level*.22,2.5);state.velocity.copy(facing).multiplyScalar(speed);state.velocity.y=0;impact(state.ball.position,d<1.2);alert(d<1.2?'No tempo certo.':'Boa! Continua comigo.',1.4);state.hits++}else{tone(240,.08,'triangle');alert('Espere a estrela chegar no círculo.',1.2)}}
function damage(){if(invincible>0||winPending||$('#modal').open)return;if(mode==='training'){launchIncoming();alert('Tudo bem. Esse é só o nosso treino.');return}hp--;invincible=1.2;impact(hero.position.clone().add(V(0,1,0)));$('#health').innerHTML=Array.from({length:Math.max(0,hp)},()=>'<svg><use href="#heart"/></svg>').join('');tone(130,.22,'triangle');if(hp<=0){paused=true;modal('<div class="eyebrow">SEU CARINHO CONTINUA AQUI</div><h2>A gente pode recomeçar.</h2><p>Você não perdeu cartas ou estrelas. Quer tentar de novo?</p>',[['Tentar novamente',startLevel,true],['Descansar',showMenu]])}}
function fail(){invincible=0;hp=1;damage()}
function enemyDefeated(){let e=enemy();if(!e||state.rewarding)return;state.rewarding=true;state.ball.visible=false;impact(e.model.position.clone().add(V(0,1,0)),true);if(!state.training)e.model.visible=false;if(state.training){save.training=true;persist();requiredFlow=true;modal('<div class="eyebrow">TREINO CONCLUÍDO</div><h2>Agora, do mesmo lado.</h2><p>Você aprendeu a devolver a estrela. Na partida, as sombras representam coisas que pesaram entre nós. Cada uma guarda uma carta e a possibilidade de cuidar melhor um do outro.</p>',[['Entrar na partida',()=>startArena(false),true],['Meu cantinho',showMenu]]);return}letter(e.chapter,()=>{state.enemy++;state.rewarding=false;closeModal();if(state.enemy>=state.enemies.length)victory();else{launchIncoming();alert('Próxima sombra: '+enemy().name)}})}
function letter(i,after){if(save.cards.includes(i)){after();return}requiredFlow=true;if(!save.cards.includes(i)){save.cards.push(i);persist()}let c=chapters[i];$('#modal').classList.remove('healed');$('#modal').classList.add('corrupt');modal('<div class="eyebrow">'+c.date+' · CARTA SOB A SOMBRA</div><h2>'+c.name+'</h2><p>'+c.dark+'</p><p><small>Uma carta original inspirada na nossa história.</small></p>',[['Deixar entrar a luz',()=>{let b=$('#modalButtons button');b.disabled=true;$('#salvation').classList.remove('play');void $('#salvation').offsetWidth;$('#salvation').classList.add('play');chime();setTimeout(()=>{$('#modal').classList.remove('corrupt');$('#modal').classList.add('healed');modal('<div class="eyebrow">ONDE A LUZ ENCONTRA NÓS DOIS</div><h2>'+c.name+' não precisa decidir por nós.</h2><p>'+c.light+'</p><blockquote>A gente pode construir um caminho mais gentil, juntos.</blockquote>',[['Guardar essa luz',()=>{$('#modal').classList.remove('healed');requiredFlow=false;after()},true]])},1250)},true]])}
function safeChestPosition(origin,boxes){for(let radius of [1.8,1,2.7,3.6,4.5])for(let j=0;j<16;j++){let a=j/16*Math.PI*2,p=origin.clone().setY(0).add(V(Math.sin(a)*radius,0,Math.cos(a)*radius));if(Math.hypot(p.x,p.z)<(mode==='garden'?38:18)&&!collides(p.x,p.z,boxes,.9)&&pathfind(origin,p,boxes,mode==='garden'?40:19.5).length)return p}return V(0,0,12)}
function victory(){if(winPending)return;winPending=true;save.pending=save.level;persist();state.kitchen?.close();if(state.kitchen){state.kitchen.dispose();state.kitchen=null;}state.resting=false;setNight(false);for(let o of things)disposeObject(o);things=[];clearWorld();walls=[];hero.userData.body.rotation.set(0,0,0);hero.userData.cloak.visible=true;hero.userData.glow.visible=true;hero.userData.sword.visible=false;pos(hero,0,3);hero.rotation.y=Math.PI;companion.visible=true;pos(companion,1.8,2.7);companion.rotation.y=-.6;let root=track(new T.Group());scene.add(root);mesh(new T.CylinderGeometry(5.8,5.5,.5,48),'#6e8d7c',0,-.3,0,root);mesh(new T.CylinderGeometry(2,2,.08,48),'#a5aa87',0,-.02,.8,root);for(let i=0;i<16;i++){let a=i/16*Math.PI*2;foodFlower(root,Math.sin(a)*4.7,Math.cos(a)*4.7)}chest=track(chestModel(0,.8));chestTime=.001;cameraTarget.copy(V(0,1,1.5));camera.position.set(0,9,13);$('#rhythm').hidden=true;$('#controls').hidden=false;$('#hint').hidden=true;$('#health').innerHTML='';if(typeof bench!=='undefined')bench.hidden=true;if(typeof tensionUI!=='undefined')tensionUI.hidden=true;$('#enemyHud').hidden=true;$('#action').hidden=true;build=false;ghost=null;chime();alert('O caminho ficou para trás. Chegue ao baú para guardar sua lembrança.',5);let fade=$('#sceneFade');fade.classList.remove('play');void fade.offsetWidth;fade.classList.add('play')}
function foodFlower(root,x,z){box(x,.2,z,.035,.4,.035,'#99b582',root);mesh(new T.IcosahedronGeometry(.12,0),'#e2c8b7',x,.45,z,root)}
function claim(){if(!winPending||state.claimed)return;state.claimed=true;save.pending=null;let n=save.level;if(!save.wins.includes(n)){save.wins.push(n);save.stars+=30+Math.min(60,n*2);save.level++;persist()}modal('<div class="eyebrow">NÍVEL '+n+' · CONQUISTA GUARDADA</div><h2>Mais um passo, juntinhos.</h2><p>Você encontrou luz no caminho. Um cartão dessa conquista já pode ser enviado para o seu amor.</p><p>Os mimos são combinados entre vocês. Nenhum pagamento é feito pelo jogo.</p>',[['Gerar cartão',()=>receipt(n)],['Próximo mundo',startLevel,true],['Minha última carta',readFinal],['Meu cantinho',showMenu]])}
function startDefense(){mode='defense';resetWorld('village');pos(hero,0,12);yaw=0;state={chosen:-1,resting:false,money:45,income:1,computer:0,wave:1,timer:18,monster:null,target:0,monsterHp:200,monsterMax:200,phase:'preparing',path:[],attack:0,shoot:0,cycle:0,bullets:[],tick:0,slot:0,chapter:(save.level-1)%6};
for(let i=0;i<4;i++)houses.push(house(i%2?5.2:-5.2,i<2?-5:4,i));walls=wallsFor(houses);state.monster=track(shadowEnemy(0,-16,'#806195'));state.monster.visible=true;for(let i=0;i<3;i++){let n=track(avatar(['#9dbbba','#c9b68f','#a9a1c2'][i],i===1));pos(n,-1+i,12+i);npcs.push({model:n,house:-1,path:[],settled:false})}$('#modeName').textContent='VILA DO RECOMEÇO';$('#title').textContent='Nível '+save.level+' · Nosso refúgio';$('#objective').textContent='Entre em uma casa e use “Escolher refúgio”. Os companheiros ocuparão as outras.';$('#action').hidden=true;$('#shop').hidden=false;alert('Escolha um cantinho para cuidar.');updateHud()}
function chooseHome(i){state.chosen=i;houses[i].occupied=true;state.timer=18;let remaining=houses.map((h,j)=>j).filter(j=>j!==i);npcs.forEach((n,j)=>{n.house=remaining[j];let h=houses[n.house];n.path=pathfind(n.model.position,{x:h.x,z:h.z+1},walls);h.occupied=true});alert('Refúgio escolhido. Descanse na cama para gerar luar.');$('#shop').hidden=false}
function inside(h,p=hero.position){return Math.abs(p.x-h.x)<2.6&&Math.abs(p.z-h.z)<2.6}
function navigateMonster(dest){state.path=pathfind(state.monster.position,dest,walls)}
function movePath(o,path,dt,speed){if(!path.length)return false;let p=path[0],d=dist(o.position,p);if(d<.12){path.shift();return path.length>0}let dx=(p.x-o.position.x)/d,dz=(p.z-o.position.z)/d;o.position.x+=dx*Math.min(speed*dt,d);o.position.z+=dz*Math.min(speed*dt,d);o.rotation.y=Math.atan2(dx,dz);return true}
function nextDoor(){let ids=houses.map((h,i)=>i).filter(i=>houses[i].occupied&&!houses[i].broken);if(!ids.length){damage();return}let cursor=state.target;state.target=ids.find(i=>i>cursor)??ids[0];let h=houses[state.target];state.phase='walking';navigateMonster({x:h.x,z:h.z+4.15});state.timer=10;alert('A sombra está procurando outra porta.',2)}
function retreat(){state.phase='retreat';navigateMonster({x:0,z:-16});state.timer=0;alert('A sombra está recuando para se recuperar.',3)}
function shop(){if(mode!=='defense'||state.chosen<0){alert('Escolha uma casa primeiro.');return}let h=houses[state.chosen];let entries=[['Renda do descanso',18*state.income,'Mais 4 luar por segundo','income'],['Computador',35*(state.computer+1),'Renda extra mesmo enquanto você anda','computer'],['Reforçar porta',25*h.level,'Aumenta resistência e repara a porta','door'],['Instalar torreta',35+15*h.turrets.length,'Você escolhe a posição dentro da sua casa','turret'],['Melhorar torretas',40*(1+(h.towerLevel||0)),'Mais dano em todas as suas torretas','upgrade']];modal('<div class="eyebrow">OFICINA · '+Math.floor(state.money)+' LUAR</div><h2>Cuidar do nosso cantinho</h2>'+entries.map(([n,c,d,k])=>'<button class="entry" data-buy="'+k+'" '+(state.money<c||k==='upgrade'&&!h.turrets.length?'disabled':'')+'>'+n+' · '+c+'<small>'+d+'</small></button>').join(''),[['Voltar',closeModal]]);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>purchase(b.dataset.buy))}
function purchase(k){let h=houses[state.chosen],cost={income:18*state.income,computer:35*(state.computer+1),door:25*h.level,turret:35+15*h.turrets.length,upgrade:40*(1+(h.towerLevel||0))}[k];if(state.money<cost)return;if(k==='turret'){closeModal();build=true;ghost??=track(mesh(new T.CylinderGeometry(.45,.5,.2,12),'#b2e0cf',hero.position.x,.3,hero.position.z));ghost.material=ghost.material.clone();ghost.material.transparent=true;ghost.material.opacity=.65;ghost.visible=true;alert('Toque no chão da sua casa para posicionar. Use “Cancelar” para sair.',5);return}state.money-=cost;if(k==='income')state.income++;if(k==='computer')state.computer++;if(k==='door'){h.level++;h.maxHp+=100;h.hp=Math.min(h.maxHp,h.hp+130)}if(k==='upgrade')h.towerLevel=(h.towerLevel||0)+1;chime();shop()}
function placeTower(p){let h=houses[state.chosen];p.x=Math.round(p.x*2)/2;p.z=Math.round(p.z*2)/2;let cost=35+15*h.turrets.length;if(!inside(h,p)||Math.abs(p.x-h.x)>2.25||Math.abs(p.z-h.z)>2.25||collides(p.x,p.z,walls,.5)||dist(hero.position,p)<.7||dist(p,{x:h.x,z:h.z+2})<1.05){alert('Deixe espaço para a porta, os móveis e para caminhar.');return}if(state.money<cost){alert('Falta luar para essa torreta.');return}state.money-=cost;let m=track(turret(p.x,p.z));h.turrets.push({x:p.x,z:p.z,model:m,cool:0});walls=wallsFor(houses);burst(p.clone().add(V(0,.6,0)),'#bdedcf',20);build=false;if(ghost)ghost.visible=false;tone(740,.2,'triangle');alert('Torreta instalada. Ela protege o seu refúgio.')}
function startGarden(){mode='garden';resetWorld();environment.visible=false;let forest=buildForest();track(forest.root);pos(hero,0,27);cameraTarget.copy(hero.position);camera.position.set(0,11,42);hero.rotation.y=Math.PI;yaw=0;companion.visible=true;pos(companion,0,-29);companion.rotation.y=0;hero.userData.sword.visible=false;hero.userData.glow.visible=false;state={checkpoint:0,points:[V(7,0,18),V(3,0,3),V(-6,0,-2),V(-3,0,-17),V(6,0,-22)],respawn:V(0,0,27),flame:0,cooldown:0,elapsed:0,chapter:1,done:false,fireflies:[],rests:[],hazards:[],forest,riverTime:0,pulse:0};
walls=forest.blockers;
for(let i=0;i<state.points.length;i++){let p=state.points[i];track(ring(p.x,p.z,.8,'#a3ac90'));let l=track(new T.PointLight('#d6dca4',0,4,1.4));l.position.copy(p).setY(1);scene.add(l);state.rests.push(l);for(let j=0;j<5;j++){let f=track(new T.Mesh(new T.SphereGeometry(.035,6,5),new T.MeshBasicMaterial({color:'#cddf9e',transparent:true,opacity:.7})));f.position.copy(p).add(V((j-2)*.22,1+j*.1,0));scene.add(f);state.fireflies.push({model:f,origin:f.position.clone(),index:i})}}
setNight(true);let moonFill=track(new T.HemisphereLight('#8298c0','#273528',.085));scene.add(moonFill);state.lighter=track(new T.PointLight('#ffba6b',0,12,1.25));state.flameMesh=track(new T.Mesh(new T.SphereGeometry(.065,8,8),new T.MeshBasicMaterial({color:'#ffe0a3'})));state.flameMesh.scale.y=2;state.flameMesh.visible=false;state.goalLight=track(new T.PointLight('#f3d3a1',2.5,5,1.3));state.goalLight.position.set(0,1.5,-29);state.beacon=track(new T.Mesh(new T.OctahedronGeometry(.1),new T.MeshBasicMaterial({color:'#f4dba8'})));state.beacon.position.set(0,2.5,-29);scene.add(state.lighter,state.flameMesh,state.goalLight,state.beacon);
$('#modeName').textContent='CAMINHO DOS VAGALUMES';$('#title').textContent='Até encontrar você';$('#objective').textContent='Risque a chama para ver por 1 segundo. Os vagalumes marcam os pontos de descanso.';$('#action span').textContent='ACENDER';$('#action use').setAttribute('href','#star');$('#health').innerHTML='';alert('Mesmo no escuro, tem um caminho até mim.',4);
modal('<div class="eyebrow">UMA TRAVESSIA ATÉ NÓS</div><h2>Uma pequena luz de cada vez.</h2><p>O cenário fica escuro. Toque em ACENDER para iluminar seus passos por cerca de um segundo. A chama pode ser usada de novo após uma breve pausa, sem gastar combustível.</p><p>Siga os grupos de vagalumes e chegue aos cinco círculos de descanso. Eles guardam seu progresso. Depois, encontre seu amor sob a pequena estrela dourada.</p><p>Atravesse duas pontes estreitas, contorne os troncos e procure a trilha entre os arbustos. Cair no riacho devolve você ao último descanso, sem perder vida. Som é opcional.</p>',[['Acender o primeiro passo',()=>{closeModal();ignite()},true],['Meu cantinho',showMenu]])}
