function updateRhythm(dt){state.laneFlash=state.laneFlash.map((v,i)=>{let n=Math.max(0,v-dt);let b=document.querySelector('#rhythm [data-lane="'+i+'"]');if(b)b.style.background=n>0?'#bba884':'#293a58df';return n});state.elapsed+=dt;$('#objective').textContent='Acertos: '+state.hit+' / '+state.total+' · sequência: '+state.combo+' · perfeitos: '+state.perfect+' · erros livres: '+Math.max(0,state.total-Math.ceil(state.total*.65)-state.miss)+'.';let b=Math.floor(state.elapsed/state.interval);if(b!==beat){beat=b;tone(b%4?130:180,.07,'sine',.025)}for(let n of state.notes){if(n.done)continue;let dz=(n.at-state.elapsed)*5;n.model.position.set((n.lane-1.5)*1.2,.4,6-dz);n.model.visible=dz<19&&dz>-.8;n.model.rotation.y+=dt*2;if(state.elapsed>n.at+.27){n.done=true;n.model.visible=false;state.combo=0;state.miss++;tone(150,.08,'triangle');if(state.miss>state.total-Math.ceil(state.total*.65)){fail();return}}}if(state.notes.every(n=>n.done)){if(state.hit>=Math.ceil(state.total*.65))letter(state.chapter,()=>{closeModal();victory()});else fail()}}
