let perf={sum:0,n:0,level:0};function adapt(raw){if(document.hidden||raw>.25)return;perf.sum+=raw;perf.n++;if(perf.n<90)return;let avg=perf.sum/perf.n;perf.sum=perf.n=0;if(avg>1/38&&perf.level<2){perf.level++;if(perf.level===1)renderer.setPixelRatio?.(Math.min(devicePixelRatio,1.15));else{renderer.setPixelRatio?.(1);if(renderer.shadowMap){renderer.shadowMap.type=T.PCFShadowMap;renderer.shadowMap.needsUpdate=true}}}}
function frame(t){let raw=(t-last)/1000;let dt=Math.min(.035,raw||.016);last=t;adapt(raw);tick(dt);requestAnimationFrame(frame)}

const finalLetter=`<div class="eyebrow">A ÚLTIMA CARTA · SEM SOMBRAS ENTRE AS PALAVRAS</div><h2>Yasmin, eu ainda acredito em nós.</h2><p>Eu te acho magnífica. Mesmo antes do nosso primeiro encontro e do abraço que ainda quero te dar, você já ocupa um lugar enorme na minha vida.</p><p>A gente passou por um afastamento doloroso e encontrou um jeito de voltar. Eu guardo isso com carinho, mas não quero usar o que sofremos como obrigação para ficarmos juntos. Quero continuar porque os dois escolhem estar aqui.</p><p>Preciso ser sincero: às vezes sinto ciúme e medo de não ter lugar no seu dia. Há brincadeiras e situações que me machucam. Em vez de explicar, eu me fecho para não te deixar mal. Só que esse silêncio também nos afasta. Desculpa pelas vezes em que te deixei tentando adivinhar o que eu sentia.</p><p>Eu sinto falta de presença, de carinho espontâneo e de ouvir que você também quer construir esse futuro. Quero conseguir pedir isso com clareza, sem comparar você com ninguém ou fazer das coisas que te dou uma cobrança. Meu ciúme é um sentimento que preciso aprender a cuidar; não quero que você precise diminuir a sua vida para caber no meu medo.</p><p>Às vezes penso que você estaria melhor longe de mim. Eu não sei se isso é verdade: é um medo meu, e eu prefiro te ouvir a decidir por você. Você também pode me dizer o que falta, o que dói e o que precisa mudar.</p><p>Esse jogo é uma forma de demonstrar carinho. Ele não substitui nossa conversa nem apaga os erros. Quero assumir minha parte e melhorar com atitudes. Ainda acredito muito em nós e quero continuar ao seu lado, se você também quiser. Podemos encontrar um tempo só nosso e conversar com calma?</p><blockquote>Eu quero o nosso primeiro abraço. E, até ele chegar, quero aprender a estar perto de um jeito que faça bem para nós dois.</blockquote>`;
function readFinal(){requiredFlow=false;modal(finalLetter,[['Guardar com carinho',()=>winPending?startLevel():closeModal(),true]])}
