function serveFood(){if(mode!=='restaurant'||$('#modal').open||paused||winPending)return;if(dist(hero.position,{x:0,z:2})>4){alert('Chegue perto do balcão para servir.');return}if(state.assembled.join('|')!==state.recipe.join('|')||!state.kitchen.rolled){alert('Confira o pedido. Você pode limpar o preparo e tentar de novo.');tone(200,.1);return}state.served++;state.money+=15;impact(V(0,1.5,0),true);if(state.served>=state.goal){bench.hidden=true;letter(6,()=>{closeModal();victory()})}else{state.customers.forEach((c,i)=>{c.rotation.y=Math.PI;c.position.z=-3-i});newOrder();alert('Pedido entregue com carinho.')}}
