let adventures=document.createElement('button');adventures.textContent='Aventuras';$('#menu nav').append(adventures);adventures.onclick=()=>modal('<div class="eyebrow">ESCOLHA SEU CAMINHO</div><h2>Seis jeitos de encontrar luz.</h2><p>A campanha alterna os desafios. Aqui você pode escolher o que quer jogar agora.</p>',[['Estrela e espada',()=>save.training?startArena(false):start(),true],['Defesa do refúgio',startDefense],['Caminho dos vagalumes',startGarden],['Melodia de nós',startRhythm],['Shawarma da Yasmin',startRestaurant],['Pesca no lago',startFishing],['Voltar',closeModal]]);

let guideKey='',guideAge=0;
function showHelp(force=false){if(winPending){modal('<div class="eyebrow">SUA CONQUISTA ESTÁ SALVA</div><h2>Abra sua lembrança.</h2><p>Aproxime-se do baú nesta clareira e toque em ABRIR BAÚ. A tampa abre e a carta aparece. Se sair, o menu permite resgatar a conquista salva.</p>',[['Continuar',closeModal,true]]);return}let info=guides[mode];if(!info){modal('<div class="eyebrow">UM JOGO NO SEU RITMO</div><h2>Como você quer jogar?</h2><p>Escolha uma aventura no menu. Cada uma explica os primeiros passos. Você pode pausar sempre que precisar.</p>',[['Modo leve',toggleLowPower],['Voltar',closeModal]]);return}save.tutorials??={};if(!force&&save.tutorials[mode]){if(mode==='garden')closeModal();return}save.tutorials[mode]=true;persist();requiredFlow=false;modal('<div class="eyebrow">COMO JOGAR · '+info.title+'</div><h2>Um passo de cada vez.</h2><ol class="guideSteps">'+info.steps.map(t=>'<li>'+t+'</li>').join('')+'</ol><p class="guideFoot">Se o jogo ficar pesado, ative o modo leve ou faça uma pausa. Nosso tempo junto não precisa virar obrigação.</p>',[['Entendi, vamos jogar',()=>{closeModal();guideKey='';if(mode==='garden')ignite()},true],['Modo leve',toggleLowPower]])}
function toggleLowPower(){save.lowPower=!save.lowPower;renderer.setPixelRatio?.(save.lowPower?1:Math.min(devicePixelRatio,1.7));if(renderer.shadowMap)renderer.shadowMap.enabled=!save.lowPower;persist();alert(save.lowPower?'Modo leve ativado. Menos sombras, o mesmo progresso.':'Qualidade normal ativada.');closeModal()}
function updateGuidance(dt){guideAge+=dt;let key='',text='';if(winPending){key='reward';text='Uma clareira só para sua lembrança. Chegue perto e abra o baú.'}else if(mode==='garden'){key='forest-'+state.checkpoint;text=['Siga os vagalumes até o primeiro descanso.','À frente, uma ponte. Atravesse pelo meio das tábuas.','Primeira travessia feita. Procure a trilha entre os arbustos.','A próxima ponte é mais estreita. Vá com calma.','As pontes ficaram para trás. Siga a curva da trilha.','A estrela dourada marca onde eu estou esperando.'][state.checkpoint]}else if(mode==='defense'){key=state.chosen<0?'home-pick':state.resting?'home-rest':state.phase==='preparing'?'home-build':state.phase;text=state.chosen<0?'Entre numa casa pela porta e escolha seu refúgio.':state.resting?'O descanso gera luar. Use CONSTRUIR para melhorar o refúgio.':state.phase==='preparing'?'Feche a porta e prepare as melhorias antes da sombra chegar.':({walking:'A sombra está procurando outra porta.',attack:'Ela está atacando. Reforce a porta e as torretas.',retreat:'Ela recuou. Aproveite para melhorar seu refúgio.',sleep:'Ela se recupera no esconderijo e voltará mais forte.'})[state.phase]}else if(mode==='fishing'){key='fish-'+state.phase;text=({ready:'Aproxime-se do píer e lance a linha.',waiting:'Observe a boia. Fisgue quando ela mergulhar.',bite:'Agora! Toque em FISGAR.',reeling:'Segure e solte: mantenha a tensão na faixa verde.'})[state.phase]}else if(mode==='restaurant'){key='cook-'+state.served+'-'+state.assembled.length+'-'+!!state.kitchen?.active;text=state.kitchen?.active?'Siga a guia. Seu prazo está pausado.':state.kitchen?.rolled?'Pronto. Sirva o shawarma.':'O ingrediente destacado é sua próxima etapa.'}else if(mode==='rhythm'){key=state.elapsed<1?'rhythm-ready':'rhythm-play';text=state.elapsed<1?'Prepare as quatro setas. Espere a nota chegar ao círculo.':'Toque na chegada ao círculo. Cada acerto encontra o ritmo.'}else{key=mode+'-'+(state.enemy||0);text=mode==='training'?'Espere a estrela entrar no círculo e toque em REBATER.':'Aproxime a estrela do círculo. Rebata e siga em frente.'}if(key!==guideKey){guideKey=key;guideAge=0;if(text)alert(text,4)}document.body.dataset.mode=mode;let statusModes=['garden','arena','training','rhythm','fishing'];$('#actionInfo').hidden=!statusModes.includes(mode)||winPending;if(mode==='fishing')$('#actionInfo').textContent='Peixes · '+state.caught+' / '+state.goal;if(mode==='training')$('#actionInfo').textContent='Treino · '+(3-enemy().hp)+' / 3';if(mode==='arena')$('#actionInfo').textContent='Sombra · '+(state.enemy+1)+' / '+state.enemies.length;if(mode==='rhythm')$('#actionInfo').textContent='Acertos '+state.hit+' / '+state.total+' · erros livres '+Math.max(0,state.total-Math.ceil(state.total*.65)-state.miss);let value=$('#health').innerHTML;if($('#vitals').innerHTML!==value)$('#vitals').innerHTML=value}
const startArenaOriginal=startArena;startArena=function(training=false){startArenaOriginal(training);guideKey='';if(!training)showHelp()};
for(let pair of [[()=>startDefense,v=>startDefense=v],[()=>startGarden,v=>startGarden=v],[()=>startRhythm,v=>startRhythm=v],[()=>startRestaurant,v=>startRestaurant=v],[()=>startFishing,v=>startFishing=v]]){let original=pair[0]();pair[1]((...args)=>{original(...args);guideKey='';showHelp()})}
let helpButton=document.createElement('button');helpButton.id='helpGame';helpButton.textContent='?';helpButton.setAttribute('aria-label','Como jogar');helpButton.onclick=()=>showHelp(true);document.querySelector('header').append(helpButton);let vitals=document.createElement('div');vitals.id='vitals';document.querySelector('header').append(vitals);
let sketchButton=document.createElement('button');sketchButton.textContent='Rabiscos';sketchButton.onclick=()=>{let wasPaused=paused;paused=true;openSketch(()=>paused=wasPaused)};$('#menu nav').append(sketchButton);if(save.lowPower){renderer.setPixelRatio?.(1);if(renderer.shadowMap)renderer.shadowMap.enabled=false}

let pendingButton=document.createElement('button');pendingButton.textContent='Resgatar conquista salva';pendingButton.className='primary';pendingButton.hidden=!save.pending;$('#menu').append(pendingButton);pendingButton.onclick=()=>{if(save.pending===save.level){winPending=true;state.claimed=false;claim()}else{save.pending=null;persist();pendingButton.hidden=true}};showMenu();cameraTarget.set(0,1,0);camera.position.set(10,14,18);$('#loading').hidden=true;requestAnimationFrame(frame);
